<?php
declare(strict_types=1);
require_once __DIR__.'/includes/session_org.php';require_once __DIR__.'/includes/org_context.php';require_once __DIR__.'/includes/org_manager_guard.php';require_once __DIR__.'/includes/org_sales.php';require_once __DIR__.'/includes/org_crm.php';
org_require_manager();org_require_commerce_seller();org_ecommerce_ensure_schema($dbh);if(!function_exists('h')){function h(string $v):string{return htmlspecialchars($v,ENT_QUOTES,'UTF-8');}}
$orgId=(int)orgActiveOrgId();$id=(int)($_GET['id']??0);$anchor=org_sales_order($dbh,$orgId,$id);if(!$anchor||trim((string)$anchor['buyer_email'])===''){header('Location: sales_management.php#customers');exit;}$email=trim((string)$anchor['buyer_email']);
$st=$dbh->prepare('SELECT * FROM org_orders WHERE org_id=:org AND LOWER(TRIM(buyer_email))=LOWER(:email) ORDER BY created_at DESC,id DESC');$st->execute([':org'=>$orgId,':email'=>$email]);$orders=$st->fetchAll(PDO::FETCH_ASSOC)?:[];
$name=trim((string)($orders[0]['buyer_name']??''))?:'Customer';$phone=trim((string)($orders[0]['buyer_phone']??''));$address=trim((string)($orders[0]['delivery_address']??''));$currency=(string)($orders[0]['currency']??'USD');$count=count($orders);$spent=array_sum(array_map(static fn($o)=>(int)$o['total_cents'],$orders));$avg=$count?(int)round($spent/$count):0;$joinedTs=min(array_map(static fn($o)=>strtotime((string)$o['created_at'])?:time(),$orders));$lastTs=strtotime((string)$orders[0]['created_at'])?:time();$active=$lastTs>=time()-180*86400;$cid='CUST-'.str_pad((string)$id,7,'0',STR_PAD_LEFT);$initials='';foreach(preg_split('/\s+/',$name)?:[] as $part){$initials.=mb_strtoupper(mb_substr($part,0,1));if(mb_strlen($initials)>=2)break;}
$contact=null;try{$st=$dbh->prepare('SELECT * FROM org_crm_contacts WHERE org_id=:org AND LOWER(TRIM(email))=LOWER(:email) AND is_deleted=0 LIMIT 1');$st->execute([':org'=>$orgId,':email'=>$email]);$contact=$st->fetch(PDO::FETCH_ASSOC)?:null;}catch(Throwable $e){}
$refundCents=0;try{$st=$dbh->prepare("SELECT COALESCE(SUM(o.total_cents),0) FROM org_order_returns r JOIN org_orders o ON o.id=r.order_id WHERE r.org_id=:org AND LOWER(TRIM(o.buyer_email))=LOWER(:email) AND r.status='refunded'");$st->execute([':org'=>$orgId,':email'=>$email]);$refundCents=(int)$st->fetchColumn();}catch(Throwable $e){}
$customerIds=[];try{$st=$dbh->prepare("SELECT MIN(id) FROM org_orders WHERE org_id=:org AND buyer_email IS NOT NULL AND TRIM(buyer_email)<>'' GROUP BY LOWER(TRIM(buyer_email)) ORDER BY MAX(created_at) DESC");$st->execute([':org'=>$orgId]);$customerIds=array_map('intval',$st->fetchAll(PDO::FETCH_COLUMN));}catch(Throwable $e){}$pos=array_search($id,$customerIds,true);$prev=$pos!==false&&isset($customerIds[$pos-1])?$customerIds[$pos-1]:0;$next=$pos!==false&&isset($customerIds[$pos+1])?$customerIds[$pos+1]:0;
$pageTitle=$cid;require_once __DIR__.'/includes/org_page_shell.php';org_page_shell_open($pageTitle,'<link rel="stylesheet" href="css/commerce-hub.css?v=17"><link rel="stylesheet" href="css/sales-azia.css?v=6">');org_page_body_open('commerce-page');
?>
